return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'sq_AL','project-id-version'=>'Events Manager','pot-creation-date'=>'2026-11-16T04:45:03+00:00','po-revision-date'=>'2026-11-15 04:18:17+0000','x-generator'=>'Pixelite GlotPress Sync','messages'=>[' Maximum size permitted by WordPress is %s.'=>' Madhësia maksimale e lejuar nga WordPress është %s.',' is required.'=>' është e domosdoshme.','"%1$s" could not be created: %2$s'=>'"%1$s" nuk u krijua dot: %2$s','"%1$s" is not a field. Fields: %2$s.'=>'"%1$s" nuk është fushë. Fusha: %2$s.','"%s" is neither a media ID nor a web address that can be reached.'=>'"%s" nuk është as ID media, as adresë web që mund të arrihet.','"All events" link text'=>'Tekst lidhjeje për “krejt veprimtaritë”','#s will be replaced by the date format below'=>'#s do të zëvendësohet nga formati i datave më poshtë','%1$s could not be updated yet, and Events Manager will keep retrying in the background: %2$s'=>'%1$s s’u përditësua dot ende dhe Events Manager do të vazhdojë të provojë në prapaskenë: %2$s','%1$s of %2$s'=>'%1$s nga %2$s','%1$s recommends %2$s version %3$s or greater installed. Earlier versions may cause unexpected issues.'=>'%1$s këshillon që të jetë instaluar %2$s version %3$s ose më i ri. Versione më të vjetër mund të shkaktojnë probleme të papritura.','%1$s requires %2$s version %3$s or greater installed.'=>'%1$s lyp që të jetë instaluar %2$s version %3$s ose më i ri.','%1$s was updated, but the result could not be stored: %2$s'=>'%1$s u përditësua, por rezultati s’u ruajt dot: %2$s','%1$s will be set up automatically on %2$s.'=>'%1$s do të ujdiset automatikisht më %2$s.','%1$s: %2$d rows imported, %3$d skipped.'=>'%1$s: %2$d rreshta u importuan, %3$d u anashkaluan.','%d Attendees'=>'%d Pjesëmarrës','%d Pattern'=>'%d Model' . "\0" . '%d Modele','%d Spaces'=>'%d Hapësira','%d Tickets'=>'%d Bileta','%d date'=>'%d datë' . "\0" . '%d data','%d events have been %s as they no longer match the recurrence pattern